.mirror-root .is-layout-constrained > .alignleft{float: left;margin-inline-start: 0;margin-inline-end: 2em;}
.mirror-root .is-layout-constrained > .alignright{float: right;margin-inline-start: 2em;margin-inline-end: 0;}
