.mirror-root :root :where(.is-layout-grid){gap: var(--theme-content-spacing);}
.mirror-root .is-layout-flow > .alignleft{float: left;margin-inline-start: 0;margin-inline-end: 2em;}
.mirror-root .is-layout-flow > .alignright{float: right;margin-inline-start: 2em;margin-inline-end: 0;}
.mirror-root .is-layout-flow > .aligncenter{margin-left: auto !important;margin-right: auto !important;}
.mirror-root .is-layout-constrained > .alignleft{float: left;margin-inline-start: 0;margin-inline-end: 2em;}
.mirror-root .is-layout-constrained > .alignright{float: right;margin-inline-start: 2em;margin-inline-end: 0;}
.mirror-root .is-layout-constrained > .aligncenter{margin-left: auto !important;margin-right: auto !important;}
.mirror-root .is-layout-constrained > :where(:not(.alignleft):not(.alignright):not(.alignfull)){max-width: var(--wp--style--global--content-size);margin-left: auto !important;margin-right: auto !important;}
.mirror-root .is-layout-constrained > .alignwide{max-width: var(--wp--style--global--wide-size);}
.mirror-root .is-layout-flex{display: flex;}
.mirror-root .is-layout-flex{flex-wrap: wrap;align-items: center;}
.mirror-root .is-layout-flex > :is(*, .mirror-root div){margin: 0;}
.mirror-root .is-layout-grid{display: grid;}
.mirror-root .is-layout-grid > :is(*, .mirror-root div){margin: 0;}
.mirror-root{padding-top: 0px;padding-right: 0px;padding-bottom: 0px;padding-left: 0px;}
